-- Biaya per jabatan di COA 5201010101 (Biaya Umum/overhead). Satu baris teks per (jabatan, tipe, BA): JAB|TIPE|BA|JT YTD|ORANG YTD|JT BLN LAPORAN|ORANG BLN LAPORAN|HK YTD|HK BLN LAPORAN
-- Pisahkan ke work/oj.txt (7 kolom pertama) dan work/oj_hk.txt (JAB|TIPE|BA|HK YTD|HK BLN), lalu: python3 oj_load.py w10/oj.txt w10/r_oj.json w10/oj_hk.txt
-- Catatan: INT_COST_ALOKASI = alokasi gaji per karyawan (TM+TBM); total per BA tidak sama dgn PRS_COST.OPEX_BIAYA_UMUM (TM saja). Ganti '2026-10-01' dan batas BULAN sesuai bulan laporan.
-- Hasil YTD Okt 2026 untuk kontrol: JT 2121 10.231,0; 2124 5.029,3; 2123 1.988,9; 2131 1.069,2.
SELECT COALESCE(NULLIF(TRIM(KODE_JABATAN),''),'(TANPA JABATAN)')||'|'||COALESCE(NULLIF(TRIM(TIPE_JABATAN),''),'-')||'|'||KODE_BA||'|'||ROUND(SUM(AMOUNT)/1e6,3)||'|'||COUNT(DISTINCT NIK_KARYAWAN)||'|'||ROUND(SUM(IFF(DATE_TRUNC('month',BULAN)='2026-10-01',AMOUNT,0))/1e6,3)||'|'||COUNT(DISTINCT IFF(DATE_TRUNC('month',BULAN)='2026-10-01',NIK_KARYAWAN,NULL))||'|'||ROUND(COALESCE(SUM(HK),0),1)||'|'||ROUND(COALESCE(SUM(IFF(DATE_TRUNC('month',BULAN)='2026-10-01',HK,0)),0),1) r
FROM PRD_DB_INTEGRATION.INT_COST.INT_COST_ALOKASI WHERE COA='5201010101' AND KODE_BA IN ('2121','2124','2123','2131') AND BULAN BETWEEN '2026-01-01' AND '2026-10-31'
GROUP BY COALESCE(NULLIF(TRIM(KODE_JABATAN),''),'(TANPA JABATAN)'),COALESCE(NULLIF(TRIM(TIPE_JABATAN),''),'-'),KODE_BA ORDER BY 1;
